package com.example.starter.race.domain;

import org.junit.jupiter.api.Test;

import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * {@link ResultCalculator} 纯逻辑单元测试：加时、取消资格、撤销恢复、并列跳号与展示顺序。
 */
class ResultCalculatorTest {

    private record Runner(String bib, Long finishTimeMs) implements ResultCalculator.RunnerView {
    }

    private record Penalty(
            String bib,
            PenaltyType type,
            Long amountMs,
            boolean revoked
    ) implements ResultCalculator.PenaltyView {
    }

    @Test
    void 按总耗时升序排名并累加全部未撤销加时() {
        List<Runner> runners = List.of(
                new Runner("A", 1000L),
                new Runner("B", 1000L),
                new Runner("C", 2000L));
        List<Penalty> penalties = List.of(
                new Penalty("A", PenaltyType.ADD_TIME, 500L, false),
                new Penalty("B", PenaltyType.ADD_TIME, 100L, false),
                new Penalty("B", PenaltyType.ADD_TIME, 200L, false));

        List<ResultEntry> entries = ResultCalculator.compute(runners, penalties);

        assertThat(entries).extracting(ResultEntry::bib).containsExactly("B", "A", "C");
        assertThat(entries).extracting(ResultEntry::rank).containsExactly(1, 2, 3);
        assertThat(entries.get(0).penaltyMs()).isEqualTo(300L);
        assertThat(entries.get(0).totalTimeMs()).isEqualTo(1300L);
        assertThat(entries.get(1).penaltyMs()).isEqualTo(500L);
        assertThat(entries.get(1).totalTimeMs()).isEqualTo(1500L);
        assertThat(entries.get(2).penaltyMs()).isZero();
        assertThat(entries.get(2).totalTimeMs()).isEqualTo(2000L);
        assertThat(entries).extracting(ResultEntry::status)
                .containsOnly(EntryStatus.RANKED);
    }

    @Test
    void 同耗时同名次并跳号且并列按参赛号字典序展示() {
        List<Runner> runners = List.of(
                new Runner("b10", 1000L),
                new Runner("b2", 1000L),
                new Runner("b1", 1000L),
                new Runner("c", 1500L),
                new Runner("d", 1500L),
                new Runner("e", 2000L));

        List<ResultEntry> entries = ResultCalculator.compute(runners, List.of());

package com.example.starter.race.persistence;

import com.example.starter.race.domain.ResultCalculator;

/**
 * runner 表行记录。
 *
 * @param id           自增主键
 * @param raceId       所属赛事ID
 * @param bib          参赛号，赛事内唯一
 * @param finishTimeMs 原始完赛耗时（毫秒，1~86400000）；null 表示计时缺失
 * @param createdAt    登记时间，Unix毫秒时间戳
 * @param updatedAt    最近一次计时修订时间，Unix毫秒时间戳
 */
public record RunnerRow(
        long id,
        String raceId,
        String bib,
        Long finishTimeMs,
        long createdAt,
        long updatedAt
) implements ResultCalculator.RunnerView {
}

package com.example.starter.race.persistence;

import com.example.starter.race.domain.RaceStatus;

/**
 * race 表行记录。
 *
 * @param raceId    赛事ID，全局唯一
 * @param version   版本号，从1开始
 * @param status    赛事状态
 * @param createdAt 创建时间，Unix毫秒时间戳
 */
public record RaceRow(String raceId, int version, RaceStatus status, long createdAt) {
}

package com.example.starter.race.persistence;

import java.util.List;

/**
 * result_snapshot 头表与其条目、分段明细合成的封榜快照。
 *
 * @param raceId     赛事ID
 * @param version    封榜时的版本号
 * @param sealedAt   封榜时间，Unix毫秒时间戳
 * @param entries    按展示顺序排列的快照条目
 * @param checkpoints 全部选手 × 全部检查点的固化明细（缺失检查点 elapsedMillis/timingId 为 null）
 */
public record SnapshotRow(
        String raceId,
        int version,
        long sealedAt,
        List<SnapshotEntryRow> entries,
        List<SnapshotCheckpointRow> checkpoints
) {

    /** 不含分段明细的兼容构造器（未配置检查点的赛事封榜）。 */
    public SnapshotRow(String raceId, int version, long sealedAt, List<SnapshotEntryRow> entries) {
        this(raceId, version, sealedAt, entries, List.of());
    }
}

package com.example.starter.race.domain;

import java.util.List;

/**
 * 单个选手的成绩条目。
 *
 * @param bib                     参赛号
 * @param rank                    名次，从1开始；并列同名次且跳号（1、1、3）；非 RANKED 为 null
 * @param status                  成绩状态
 * @param finishTimeMs            原始完赛耗时（毫秒）；计时缺失为 null
 * @param penaltyMs               全部未撤销加时处罚的合计毫秒数；无加时为 0
 * @param totalTimeMs             总耗时=原始完赛耗时+生效加时（毫秒）；未排名时为 null
 * @param checkpointCount         赛事配置的检查点总数；未配置检查点的赛事为 0
 * @param coveredCheckpointCount  该选手已有分段记录的检查点数量
 * @param missingCheckpoints      该选手尚未通过的检查点代码，按检查点顺序排列；全部覆盖或无检查点时为空列表
 */
public record ResultEntry(
        String bib,
        Integer rank,
        EntryStatus status,
        Long finishTimeMs,
        long penaltyMs,
        Long totalTimeMs,
        int checkpointCount,
        int coveredCheckpointCount,
        List<String> missingCheckpoints
) {

    /** 未配置检查点赛事使用的兼容构造器：检查点计数均为 0、缺失列表为空。 */
    public ResultEntry(
            String bib,
            Integer rank,
            EntryStatus status,
            Long finishTimeMs,
            long penaltyMs,
            Long totalTimeMs) {
        this(bib, rank, status, finishTimeMs, penaltyMs, totalTimeMs, 0, 0, List.of());
    }
}

